import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;

/**
 * Replaces the generated parser files of one package inside a jar, used by rebuild-java-parser.sh.
 *
 * All files of the package are removed except those listed as KEEP_FILE (e.g. SimplePrintVisitor.class, which is not generated by JavaCC), so that no stale
 * classes remain, and the files of SOURCE_DIR are added. All other entries are copied unchanged, including their names.
 *
 * Usage: java UpdateJar.java IN_JAR OUT_JAR SOURCE_DIR PACKAGE_PATH [KEEP_FILE...]
 */
public class UpdateJar {

	public static void main(String[] args) throws IOException {
		final File in = new File(args[0]);
		final File out = new File(args[1]);
		final File sourceDir = new File(args[2]);
		final String packagePath = args[3].endsWith("/") ? args[3] : args[3] + "/";
		final Set<String> keep = new HashSet<>(Arrays.asList(args).subList(4, args.length));

		final byte[] buffer = new byte[8192];
		try (ZipInputStream zin = new ZipInputStream(new FileInputStream(in)); ZipOutputStream zout = new ZipOutputStream(new FileOutputStream(out))) {
			for (ZipEntry entry = zin.getNextEntry(); entry != null; entry = zin.getNextEntry()) {
				final String name = entry.getName();
				final boolean inPackage = name.startsWith(packagePath) && (name.length() > packagePath.length()) && (name.indexOf('/', packagePath.length()) < 0);
				if (inPackage && !keep.contains(name.substring(packagePath.length()))) {
					continue;
				}
				final ZipEntry copy = new ZipEntry(name);
				copy.setTime(entry.getTime());
				zout.putNextEntry(copy);
				for (int n = zin.read(buffer); n > 0; n = zin.read(buffer)) {
					zout.write(buffer, 0, n);
				}
				zout.closeEntry();
			}
			final File[] files = sourceDir.listFiles();
			Arrays.sort(files);
			for (final File file : files) {
				zout.putNextEntry(new ZipEntry(packagePath + file.getName()));
				try (InputStream fin = new FileInputStream(file)) {
					for (int n = fin.read(buffer); n > 0; n = fin.read(buffer)) {
						zout.write(buffer, 0, n);
					}
				}
				zout.closeEntry();
			}
		}
	}
}
